#!/usr/bin/env python3
"""Regenerate ../data/schemes.js from the compact table below.

The website itself needs no build step: data/schemes.js is committed and read
directly by the browser. This script only exists so 130 schemes stay editable in
one line each instead of 130 hand-written JSON blocks.

Record fields, separated by "|":
  id | name | category | level | benefit | applyAt | applyLink |
  documents | occupations | states | maxIncome | gender | minAge | extraKeywords
Empty gender means "any", empty states means "all", empty maxIncome means no cap.
"""

