def build():
    schemes = []
    seen = set()
    for raw in RECORDS:
        parts = raw.split("|")
        if len(parts) != 14:
            raise ValueError(f"{parts[0]}: expected 14 fields, got {len(parts)}")
        sid, name, cat, lvl, benefit, apply_at, link, docs, occ, states, max_income, gender, min_age, kw = parts

        if sid in seen:
            raise ValueError(f"duplicate id {sid}")
        seen.add(sid)

        named = re.sub(r"[^a-z ]", "", sid.replace("-", " ")).strip()
        first_word = re.sub(r"[^a-z]", "", name.lower().split()[0])
        extra = CATEGORY_KEYWORDS.get(cat, []) + [named]
        if len(first_word) > 3 and first_word not in NAME_STOP:
            extra.append(first_word)
        keywords = sorted(set(
            [w.strip().lower() for w in kw.split(",") if w.strip()] + extra
        ))

        scheme = {
            "id": sid,
            "name": name,
            "category": cat,
            "level": lvl,
            "benefit": benefit,
            "applyAt": apply_at,
            "documents": [d.strip() for d in docs.split(",") if d.strip()] or DEFAULT_DOCS,
            "eligibility": {
                "occupations": [o.strip() for o in occ.split(",") if o.strip()],
                "states": [s.strip() for s in states.split(",") if s.strip()] or ["all"],
                "maxIncome": int(max_income) if max_income else None,
                "gender": gender.strip() or "any",
                "minAge": int(min_age) if min_age != "" else 18,
                "keywords": keywords,
            },
        }
        if link.strip():
            scheme["applyLink"] = link.strip()
        schemes.append(scheme)

    for s in schemes:
        if not s["eligibility"]["occupations"]:
            raise ValueError(f"{s['id']}: no occupations")
    return schemes


if __name__ == "__main__":
    schemes = build()
    out = os.path.join(os.path.dirname(__file__), "..", "data", "schemes.js")
    body = json.dumps(schemes, ensure_ascii=False, indent=2)
    io.open(out, "w", encoding="utf-8").write(
        "// Scheme database. Plain JS so the site works with no server (file:// blocks fetch of .json).\n"
        "// Amounts are illustrative for a student demo. Regenerate with: python tools/build_schemes.py\n"
        "window.SCHEMES = " + body + ";\n"
    )
    print(f"wrote {len(schemes)} schemes to {os.path.normpath(out)}")
